import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)
def get_pkgs(data):
    pkgs = {}
    for proj in data.get('projects', []):
        pname = proj['path']
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[(pname, pkg['id'])] = pkg['resolvedVersion']
    return pkgs
bp, ap = get_pkgs(b), get_pkgs(a)
if bp == ap:
    print('All packages resolve identically to baseline.')
else:
    for k in set(list(bp.keys()) + list(ap.keys())):
        if bp.get(k) != ap.get(k):
            print(f'DIFF {k}: {bp.get(k)} -> {ap.get(k)}')
"

